  CHECK ("due_in_days" IS NULL OR ("due_in_days" >= 0 AND "due_in_days" <= 365));
ALTER TABLE "tenants" ADD CONSTRAINT "tenants_automation_ranges"
  CHECK (cardinality("deadline_reminder_days") <= 3
    AND ("lead_follow_up_days" IS NULL OR ("lead_follow_up_days" BETWEEN 1 AND 90)));

-- Row-Level Security: every Stage 8 table is visible and writable only inside the active tenant.
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['stage_task_templates', 'deadline_reminder_logs'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I USING (tenant_id = app_setting_uuid(''app.tenant_id'')) WITH CHECK (tenant_id = app_setting_uuid(''app.tenant_id''))',
      t || '_isolation', t);
  END LOOP;
END $$;
